// Simulated telemetry frames and their validation.
//
// Telemetry in this project is SIMULATED: frames are typed into a command
// script by a person or generated by the test harness. Nothing here reads a
// physical sensor.
#pragma once

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

#include "cubesat/json.hpp"
#include "cubesat/result.hpp"

namespace cubesat {

enum class CommStatus { Up, Down };
enum class SensorStatus { Valid, Invalid };

std::string_view toString(CommStatus status);
std::string_view toString(SensorStatus status);

// Plausibility limits used for INPUT VALIDATION (is the number physically
// meaningful at all?). They are deliberately wider than the safety thresholds
// in the configuration: a value outside these limits is rejected as corrupt
// input; a value inside them is accepted and then judged by SafetyMonitor.
namespace plausibility {
constexpr double kBatteryMinV = 0.0;
constexpr double kBatteryMaxV = 20.0;
constexpr double kTempMinC = -150.0;
constexpr double kTempMaxC = 150.0;
constexpr double kAttitudeMinDeg = 0.0;
constexpr double kAttitudeMaxDeg = 180.0;
// Sequence numbers must stay exactly representable as a JSON number (2^53).
constexpr std::uint64_t kMaxSequence = 9007199254740991ULL;
}  // namespace plausibility

struct TelemetryFrame {
    std::uint64_t seq = 0;          // strictly increasing frame counter
    double battery_v = 0.0;         // bus voltage, volts
    double temp_c = 0.0;            // board temperature, degrees Celsius
    double attitude_deg = 0.0;      // absolute pointing error, degrees
    CommStatus comm = CommStatus::Up;
    SensorStatus sensors = SensorStatus::Valid;
    std::int64_t received_at_s = 0;  // simulated time the frame was accepted

    json::Value toJson() const;
};

// Parses the arguments of a TELEMETRY command, e.g.
//   seq=4 battery_v=7.4 temp_c=21.5 attitude_deg=1.2 comm=UP sensors=VALID
// Every field is required exactly once; unknown fields are rejected.
// received_at_s is left at 0 for the caller to fill in.
Result<TelemetryFrame> parseTelemetryArgs(const std::vector<std::string>& args);

// Strict decimal number parser shared by telemetry and command arguments.
// Accepts e.g. "7", "-3.5", "1e2"; rejects "", "abc", "0x10", "inf", "nan",
// "7.4V" and values that overflow a double.
bool parseStrictDouble(std::string_view text, double& out);

// Strict non-negative integer parser (digits only, no sign, no whitespace).
bool parseStrictUnsigned(std::string_view text, std::uint64_t max_value, std::uint64_t& out);

}  // namespace cubesat
